  const tas = []; // éléments : { val, priorite }

  function echanger(i, j) {
    const tmp = tas[i];
    tas[i] = tas[j];
    tas[j] = tmp;
  }

  function remonter(i) {
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (tas[parent].priorite <= tas[i].priorite) break;
      echanger(parent, i);
      i = parent;
    }
