  function descendre(i) {
    const n = tas.length;
    while (true) {
      const gauche = 2 * i + 1;
      const droite = 2 * i + 2;
      let plusPetit = i;
      if (gauche < n && tas[gauche].priorite < tas[plusPetit].priorite) plusPetit = gauche;
      if (droite < n && tas[droite].priorite < tas[plusPetit].priorite) plusPetit = droite;
      if (plusPetit === i) break;
      echanger(i, plusPetit);
      i = plusPetit;
    }
  }

  return {
    enqueue(val, priorite) {
      tas.push({ val, priorite });
      remonter(tas.length - 1);
    },
    dequeue() {
      if (tas.length === 0) return undefined;
      const min = tas[0];
      const dernier = tas.pop();
      if (tas.length > 0) {
        tas[0] = dernier;
        descendre(0);
      }
      return min;
    },
    taille() {
      return tas.length;
    }
  };
}
