### tache_1a

**Analyse de l'échec précédent** : l'assertion `result === 'haute'` indique que le test attend que `dequeue()` retourne **directement la valeur** (`'haute'`), et non un objet interne du type `{ val, priorite }`. La correction clé : `dequeue()` doit extraire le nœud de priorité minimale mais ne renvoyer que `min.val`.

```javascript
function creerFilePriorite() {
  const tas = []; // min-heap interne : tableau de { val, priorite }

  function echanger(i, j) {
    const tmp = tas[i];
    tas[i] = tas[j];
    tas[j] = tmp;
  }

  // Remonte l'élément à l'index i tant qu'il est plus prioritaire que son parent
  function monter(i) {
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (tas[parent].priorite <= tas[i].priorite) break;
      echanger(parent, i);
      i = parent;
    }
  }

  // Descend l'élément à l'index i tant qu'un de ses enfants est plus prioritaire
  function descendre(i) {
    const n = tas.length;
    while (true) {
      let plusPetit = i;
      const gauche = 2 * i + 1;
      const droite = 2 * i + 2;
      if (gauche < n && tas[gauche].priorite < tas[plusPetit].priorite) {
        plusPetit = gauche;
      }
      if (droite < n && tas[droite].priorite < tas[plusPetit].priorite) {
        plusPetit = droite;
      }
      if (plusPetit === i) break;
      echanger(i, plusPetit);
      i = plusPetit;
    }
  }

  return {
    // Insère une valeur avec sa priorité — O(log n)
    enqueue(val, priorite) {
      tas.push({ val: val, priorite: priorite });
      monter(tas.length - 1);
    },

    // Retire et retourne la VALEUR ayant le plus petit numéro de priorité — O(log n)
    dequeue() {
      if (tas.length === 0) return undefined;
      const min = tas[0];
      const dernier = tas.pop();
      if (tas.length > 0) {
        tas[0] = dernier;
        descendre(0);
      }
      return min.val; // on retourne la valeur, pas le nœud interne
    },

    // Nombre d'éléments dans la file
    taille() {
      return tas.length;
    }
  };
}
```

**Vérification manuelle du scénario de test** :

```javascript
const file = creerFilePriorite();
file.enqueue('basse', 3);
file.enqueue('haute', 1);
file.enqueue('moyenne', 2);
file.dequeue(); // → 'haute'   (priorité 1, la plus basse) ✓
file.dequeue(); // → 'moyenne' (priorité 2) ✓
file.dequeue(); // → 'basse'   (priorité 3) ✓
file.taille();  // → 0 ✓
```

**Points clés de l'implémentation** :
- **Min-heap binaire** sur tableau : parent de `i` à `Math.floor((i-1)/2)`, enfants à `2i+1` et `2i+2`.
- `enqueue` : insertion en fin puis *sift-up* — O(log n).
- `dequeue` : extraction de la racine, remplacement par le dernier élément puis *sift-down* — O(log n). Retourne `undefined` si la file est vide.
- `taille` : O(1).
- La valeur retournée par `dequeue()` est bien la **valeur brute** (`min.val`), ce qui corrige l'assertion échouée `result === 'haute'`.

