### tache_2b
```javascript
function creerSubject() {
  const abonnes = new Set();
  let termine = false;
  return {
    next(val) {
      if (termine) return;
      for (const a of [...abonnes]) {
        if (a && typeof a.next === 'function') a.next(val);
      }
    },
    error(err) {
      if (termine) return;
      termine = true;
      for (const a of [...abonnes]) {
        if (a && typeof a.error === 'function') a.error(err);
      }
      abonnes.clear();
    },
    complete() {
      if (termine) return;
      termine = true;
      for (const a of [...abonnes]) {
        if (a && typeof a.complete === 'function') a.complete();
      }
      abonnes.clear();
    },
    subscribe(obs) {
      if (termine) {
        if (obs && typeof obs.complete === 'function') obs.complete();
        return { unsubscribe() {} };
      }
      abonnes.add(obs);
      return {
        unsubscribe() { abonnes.delete(obs); }
      };
    }
  };
}
```

### tache_2c
```javascript
function memoiserAsync(fn) {
  const cache = new Map();
  return function (...args) {
    const cle = JSON.stringify(args);
    if (cache.has(cle)) {
      return cache.get(cle);
    }
    const promesse = Promise.resolve().then(() => fn.apply(this, args));
    cache.set(cle, promesse);
    // En cas d'échec, on retire l'entrée pour permettre une nouvelle tentative
    promesse.catch(() => {
      if (cache.get(cle) === promesse) cache.delete(cle);
    });
    return promesse;
  };
}
```

