  for (const n of noeuds) distances[n] = Infinity;
  distances[depart] = 0;
  const visites = new Set();
  while (visites.size < noeuds.size) {
    let u = null, best = Infinity;
    for (const n of noeuds) {
      if (!visites.has(n) && distances[n] < best) {
        best = distances[n];
        u = n;
      }
