function dijkstra(graphe, depart) {
  const distances = {};
  const noeuds = new Set(Object.keys(graphe));
  for (const u of Object.keys(graphe)) {
    for (const v of Object.keys(graphe[u])) noeuds.add(v);
  }
  for (const n of noeuds) distances[n] = Infinity;
  distances[depart] = 0;
  const visites = new Set();
  while (visites.size < noeuds.size) {
    let u = null, best = Infinity;
    for (const n of noeuds) {
      if (!visites.has(n) && distances[n] < best) {
        best = distances[n];
        u = n;
      }
    }
    if (u === null) break;
    visites.add(u);
    const voisins = graphe[u] || {};
    for (const v of Object.keys(voisins)) {
      const alt = distances[u] + voisins[v];
      if (alt < distances[v]) distances[v] = alt;
    }
  }
  return distances;
}

